type TreeNode = { v: number; L: TreeNode | null; R: TreeNode | null };
// Level-order array, null for a missing child: [8, 3, 12, 1, 6, 10, 14]
function buildTree(values: (number | null)[]): TreeNode | null {
  if (!values.length || values[0] == null) return null;
  const root: TreeNode = { v: values[0], L: null, R: null };
  const q = [root];
  let i = 1;
  while (q.length && i < values.length) {
    const cur = q.shift()!;
    const l = values[i++];
    if (l != null) { cur.L = { v: l, L: null, R: null }; q.push(cur.L); }
    const r = values[i++];
    if (r != null) { cur.R = { v: r, L: null, R: null }; q.push(cur.R); }
  }
  return root;
}

function briefings(root: TreeNode | null): number[][] {
  if (!root) return [];
  const out: number[][] = [];
  let q: TreeNode[] = [root];
  while (q.length) {
    out.push(q.map((n) => n.v));
    const next: TreeNode[] = [];
    for (const n of q) {
      if (n.L) next.push(n.L);
      if (n.R) next.push(n.R);
    }
    q = next;
  }
  return out;
}

function briefingsFrom(values: (number | null)[]): number[][] {
  return briefings(buildTree(values));
}
